CREATE TABLE AUTO_WRITTEN_PREM (
    POLICY_ID                      INTEGER,
    BATCH_NO                       INTEGER ,
    VEHICLE_ID                     SMALLINT,
    WRITTEN_LIABILITY_PREMIUM      numeric(15,2), /*COMPUTED BY ((select sum(v.liability_premium) from vehicles v where
                         v.vehicle_id = AUTO_WRITTEN_PREM.vehicle_id 
                         and v.batch_no <= AUTO_WRITTEN_PREM.batch_no
                         and v.policy_id = AUTO_WRITTEN_PREM.policy_id)),*/
    WRITTEN_PIP_PREMIUM  numeric(15,2), /*           COMPUTED BY ((select sum(v.PIP_PREMIUM) from vehicles v where
                         v.vehicle_id = AUTO_WRITTEN_PREM.vehicle_id 
                         and v.batch_no <= AUTO_WRITTEN_PREM.batch_no
                         and v.policy_id = AUTO_WRITTEN_PREM.policy_id)),*/
    WRITTEN_MED_PREMIUM  numeric(15,2), /*          COMPUTED BY ((select sum(v.MED_PREMIUM) from vehicles v where
                         v.vehicle_id = AUTO_WRITTEN_PREM.vehicle_id 
                         and v.batch_no <= AUTO_WRITTEN_PREM.batch_no
                         and v.policy_id = AUTO_WRITTEN_PREM.policy_id)),*/
    WRITTEN_UM_PREMIUM   numeric(15,2), /*COMPUTED BY ((select sum(v.UM_PREMIUM) from vehicles v where
                         v.vehicle_id = AUTO_WRITTEN_PREM.vehicle_id 
                         and v.batch_no <= AUTO_WRITTEN_PREM.batch_no
                         and v.policy_id = AUTO_WRITTEN_PREM.policy_id)),*/
    WRITTEN_COMP_PREMIUM  numeric(15,2), /*COMPUTED BY ((select sum(v.COMP_PREMIUM) from vehicles v where
                         v.vehicle_id = AUTO_WRITTEN_PREM.vehicle_id 
                         and v.batch_no <= AUTO_WRITTEN_PREM.batch_no
                         and v.policy_id = AUTO_WRITTEN_PREM.policy_id)),*/
    WRITTEN_SPEC_PREMIUM  numeric(15,2), /*COMPUTED BY ((select sum(v.SPEC_PREMIUM) from vehicles v where
                         v.vehicle_id = AUTO_WRITTEN_PREM.vehicle_id 
                         and v.batch_no <= AUTO_WRITTEN_PREM.batch_no
                         and v.policy_id = AUTO_WRITTEN_PREM.policy_id)),*/
    WRITTEN_COLLISION_PREMIUM  numeric(15,2), /*    COMPUTED BY ((select sum(v.COLLISION_PREMIUM) from vehicles v where
                         v.vehicle_id = AUTO_WRITTEN_PREM.vehicle_id 
                         and v.batch_no <= AUTO_WRITTEN_PREM.batch_no
                         and v.policy_id = AUTO_WRITTEN_PREM.policy_id)),*/
    WRITTEN_TOWING_PREMIUM numeric(15,2), /*         COMPUTED BY ((select sum(v.TOWING_PREMIUM) from vehicles v where
                         v.vehicle_id = AUTO_WRITTEN_PREM.vehicle_id 
                         and v.batch_no <= AUTO_WRITTEN_PREM.batch_no
                         and v.policy_id = AUTO_WRITTEN_PREM.policy_id)), */
    WRITTEN_PD_PREMIUM   numeric(15,2), /*          COMPUTED BY ((select sum(v.PD_PREMIUM) from vehicles v where
                         v.vehicle_id = AUTO_WRITTEN_PREM.vehicle_id 
                         and v.batch_no <= AUTO_WRITTEN_PREM.batch_no
                         and v.policy_id = AUTO_WRITTEN_PREM.policy_id)),*/
    WRITTEN_OCC_LIABILITY_PREMIUM  numeric(15,2), /*COMPUTED BY ((select sum(v.OCC_LIABILITY_PREMIUM) from vehicles v where
                v.vehicle_id = AUTO_WRITTEN_PREM.vehicle_id
                and v.batch_no <= AUTO_WRITTEN_PREM.batch_no
                and v.policy_id = AUTO_WRITTEN_PREM.policy_id)),*/
    WRITTEN_OCC_UM_PREMIUM numeric(15,2), /*         COMPUTED BY ((select sum(v.OCC_UM_PREMIUM) from vehicles v where
                v.vehicle_id = AUTO_WRITTEN_PREM.vehicle_id
                and v.batch_no <= AUTO_WRITTEN_PREM.batch_no
                and v.policy_id = AUTO_WRITTEN_PREM.policy_id)),*/
    WRITTEN_OCC_COMP_PREMIUM       numeric(15,2), /*COMPUTED BY ((select sum(v.OCC_COMP_PREMIUM) from vehicles v where
                v.vehicle_id = AUTO_WRITTEN_PREM.vehicle_id
                and v.batch_no <= AUTO_WRITTEN_PREM.batch_no
                and v.policy_id = AUTO_WRITTEN_PREM.policy_id)),*/
    WRITTEN_OCC_COLL_PREMIUM      numeric(15,2), /* COMPUTED BY ((select sum(v.OCC_COLL_PREMIUM) from vehicles v where
                v.vehicle_id = AUTO_WRITTEN_PREM.vehicle_id
                and v.batch_no <= AUTO_WRITTEN_PREM.batch_no
                and v.policy_id = AUTO_WRITTEN_PREM.policy_id)),*/
    WRITTEN_OCC_PD_PREMIUM         numeric(15,2) /*COMPUTED BY ((select sum(v.OCC_PD_PREMIUM) from vehicles v where
                v.vehicle_id = AUTO_WRITTEN_PREM.vehicle_id
                and v.batch_no <= AUTO_WRITTEN_PREM.batch_no
                and v.policy_id = AUTO_WRITTEN_PREM.policy_id))*/
);

