CREATE TABLE CLAIMS (
    CLAIM_NO                 text,
    DATE_REPORTED            timestamp default 'NOW',
    DATE_OCCURED             timestamp,
    ACCOUNTING_DATE          timestamp,
    CAUSE_ID                 integer,
    LOSS_DESC                text,
    DEFAULT_ADJUSTOR         text,
    ADJUSTOR_TYPE            text default 'AD',
    CLAIM_ID                 INTEGER default 0 NOT NULL,
    ADJUSTOR_NAME            text default '',
    LOSS_RESERVE             numeric(15,2), /*COMPUTED BY ((
   select sum(amount) from claim_items i 
   where i.claim_id = claims.claim_id and i.reserve_type = "LOSS")),*/
    LAE_RESERVE              numeric(15,2), /*COMPUTED BY ((
   select sum(amount) from claim_items i 
   where i.claim_id = claims.claim_id and i.reserve_type = "LAE")),*/
    LEGAL_RESERVE          numeric(15,2), /*  COMPUTED BY ((
   select sum(amount) from claim_items i 
   where i.claim_id = claims.claim_id and i.reserve_type = "LEGAL")),*/
    SALVAGE_RESERVE        numeric(15,2), /*  COMPUTED BY ((
   select sum(amount) from claim_items i 
   where i.claim_id = claims.claim_id and i.reserve_type = "SALVAGE")),*/
    SUBROGATION_RESERVE     numeric(15,2), /* COMPUTED BY ((
   select sum(amount) from claim_items i 
   where i.claim_id = claims.claim_id and i.reserve_type = "SUBROGAT")),*/
    LOSS_PAID               numeric(15,2), /* COMPUTED BY ((
   select sum(payment) from claim_Payments p 
   where p.claim_id = claims.claim_id and p.Category = "LOSS")),*/
    LAE_PAID                 numeric(15,2), /*COMPUTED BY ((
   select sum(Payment) from claim_Payments p 
   where p.claim_id = claims.claim_id and p.CATEGORY = "LAE")),*/
    LEGAL_PAID               numeric(15,2), /*COMPUTED BY ((
   select sum(Payment) from claim_Payments p 
   where p.claim_id = claims.claim_id and p.CATEGORY = "LEGAL")),*/
    SALVAGE_PAID             numeric(15,2), /*COMPUTED BY ((
   select sum(Payment) from claim_Payments p 
   where p.claim_id = claims.claim_id and p.CATEGORY = "SALVAGE")),*/
    SUBROGATION_PAID         numeric(15,2), /*COMPUTED BY ((
   select sum(Payment) from claim_Payments p 
   where p.claim_id = claims.claim_id and p.CATEGORY = "SUBROGAT")),*/
    POLICY_ID                INTEGER ,
    NOTES                    text,
    AVOID                    text default 'N',
    STATUS                   text default 'O',
    SYSDATE                  timestamp default 'now',
    CLOSED_DATE              timestamp,
    ADJUSTOR_ID              text,
    FAULT_KEY                text,
    FAULT_ID                 INTEGER,
    BATCH_NO                 INTEGER,
    IBC_CODE                 text,
    STAT1                    text,
    STAT1_ID                 INTEGER,
    STAT2                    text,
    STAT2_ID                 INTEGER,
    STAT3                    text,
    STAT3_ID                 INTEGER,
    DATE_FILED               timestamp default 'now',
    LOSS_CITY                text DEFAULT '',
    LOSS_STATE               text,
    LOSS_STATE_ID            INTEGER,
    SETTLED_CITY             text DEFAULT '',
    SETTLED_STATE            text,
    SETTLED_STATE_ID         INTEGER,
    EXPERT_RESERVE           numeric(15,2), /*COMPUTED BY ((select sum(amount) from claim_items i
                                           where i.claim_id = claims.claim_id and
                                           i.reserve_type = "EXPERT")),*/
    EXPERT_PAID              numeric(15,2), /*COMPUTED BY ((select sum(payment) from claim_Payments p
                                           where p.claim_id = claims.claim_id and
                                           p.Category = "EXPERT")),*/
    CLAIM_TYPE               text,
    CLAIM_TYPE_ID            INTEGER,
    SECONDARY_ADJUSTOR_ID    text,
    SECONDARY_ADJUSTOR_TYPE  text DEFAULT '',
    DATE_ADJUSTORREVIEW      timestamp,
    NOTES_ADJUSTORREVIEW     text,
    DRIVER_ID_SEL            SMALLINT ,
    IMPACTS_DISCOUNT         text,
    IN_SUIT                  text,
    IN_SUIT_ID               INTEGER,
    CATASTROPHE              text,
    CATASTROPHE_ID           INTEGER,
    EVENT                    text,
    EVENT_ID                 INTEGER,
    IMPACTS_DISCOUNT_ID      INTEGER,
    REFUND_RESERVE           numeric(15,2), /*COMPUTED BY (((select sum(amount) from claim_items i
  where i.claim_id = claims.claim_id
     and i.reserve_type = "REFUND"))),*/
    REFUND_PAID              numeric(15,2), /*COMPUTED BY (((select sum(Payment) from claim_Payments p
  where p.claim_id = claims.claim_id and p.CATEGORY = "REFUND"))),*/
    INJURYTYPE_KEY           text,
    INJURYTYPE_ID            INTEGER,
    STAT5                    text,
    STAT5_ID                 INTEGER ,
    STAT6                    text,
    STAT6_ID                 INTEGER ,
    STAT7                    text,
    STAT7_ID                 INTEGER ,
    STATUS_CHANGED_DATE      timestamp,
    REINSRECOV_RESERVE       numeric(15,2), /*COMPUTED BY ((select sum(amount)
  from claim_items i
 where i.claim_id = claims.claim_id
   and i.reserve_type = "REINSRECOV")),*/
    REINSRECOV_PAID          numeric(15,2), /*COMPUTED BY ((select sum(payment)
   from claim_Payments p
