    POLICYFORM_ID                 INTEGER ,
    ANNUAL_PREMIUM                numeric(15,2), /*COMPUTED BY (cast((select 
sum(annual_premium) from premium_audit a 
where a.policy_id = dwelling.policy_id and a.batch_no = dwelling.batch_no 
and a.item_id = dwelling.origin_id) as char(80))),*/
