    USER_FIELD5                   text DEFAULT '',
    USER_FIELD6                   text DEFAULT '',
    USER_FIELD7                   text DEFAULT '',
    USER_FIELD8                   text DEFAULT '',
    USER_FIELD9                   text DEFAULT '',
    USER_FIELD10                  text DEFAULT '',
