    USER_FIELD_ID2                INTEGER ,
    USER_FIELD_ID3                INTEGER ,
    USER_FIELD_ID4                INTEGER ,
    USER_FIELD_ID5                INTEGER ,
    USER_FIELD_ID6                INTEGER ,
    USER_FIELD_ID7                INTEGER ,
    USER_FIELD_ID8                INTEGER ,
    USER_FIELD_ID9                INTEGER ,
    USER_FIELD_ID10               INTEGER ,
