    COVC_PREM                     NUMERIC(15,2) ,
    COVC_ANNUAL_PREM              NUMERIC(15,2) ,
    COVD_PREM                     NUMERIC(15,2) ,
    COVD_ANNUAL_PREM              NUMERIC(15,2) ,
    RISK_NO                       SMALLINT ,
    ANNUAL_PREMIUM2               numeric(15,2), /*COMPUTED BY (cast((select
sum(annual_premium) from premium_audit a
where a.policy_id = dwelling.policy_id and a.batch_no = dwelling.batch_no
and a.item_id = dwelling.origin_id) As NUMERIC(15,2))),*/
