    ROOF_PITCH                    text,
    AMPERAGE                      text,
    HEAT_SYSTEM                   text,
    HEAT_BACKUP                   text,
    NUMBER_APARTMENTS             SMALLINT,
    PURCHASE_PRICE                NUMERIC(15,2),
    PURCHASE_DATE                 timestamp,
    SQUARE_FOOTAGE                INTEGER,
    STORIES                       SMALLINT,
    WOODSTOVE                     text,
    STORM_SHUTTERS                text,
    EXCESS_FLOOD_INSURANCE_LIMIT  NUMERIC(15,2),
