CREATE TABLE LIABILITY (
    ACTIVITY              text default 'A',
    LIAB_TYPE             text default 'P',
    LIAB_ONLY             SMALLINT ,
    COVL                  text,
    COVO                  integer,
    COVM_PERS             integer,
    COVM_ACC              integer,
    GENERAL_AGG           integer,
    PRODUCTS_AGG          integer,
    LIAB_REASON           text,
    LIAB_WAIVED           text,
    PREMIUM               numeric(15,2),
    UNIQUE_ID             integer default 0,
    ORIGIN_ID             integer,
    EFFECTIVE_DATE        timestamp,
    END_DATE              timestamp,
    PREVBAL               numeric (15,2),
    EARNEDPREM            numeric (15,2),
    ACCOUNTING_DATE       timestamp,
    RATING_STATUS         text default 'U',
    USER_ID               text,
    BATCH_NO              integer,
    STATUS                text,
    UNEARNEDPREM          numeric(15,6) ,
    WRITTENPREM           numeric(15,2), /*COMPUTED BY (PrevBal + Premium - unearnedPrem),*/
    BALANCE               numeric(15,2), /*COMPUTED BY (Premium - unearnedprem),*/
    FORM                  text,
    BASEPREM              NUMERIC(15,2) ,
    BASEEARNED            NUMERIC(15,2) ,
    BASEUNEARNED          NUMERIC(15,2) ,
    EXPIRY_DATE           timestamp,
    POLICY_ID             INTEGER ,
    COVL_ID               INTEGER ,
    ANNUAL_PREMIUM        numeric(15,2), /*COMPUTED BY (cast((select 
sum(annual_premium) from premium_audit a 
where a.policy_id = liability.policy_id and a.batch_no = liability.batch_no 
and a.item_id = liability.origin_id) as char(80))),*/
    ORIGBATCH_NO          INTEGER ,
    USER_DEF1             integer,
    USER_DEF2_KEY         text,
    USER_DEF2_ID          INTEGER,
    USER_DEF3_KEY         text,
    USER_DEF3_ID          INTEGER,
    NUM_DWELLS            integer, /*COMPUTED BY ((SELECT
        COUNT(D.POLICY_ID)
      FROM
        DWELLING D
      WHERE
        D.POLICY_ID = LIABILITY.POLICY_ID AND
        D.STATUS IN ('', 'H') AND
        D.EFFECTIVE_DATE <= LIABILITY.EFFECTIVE_DATE AND
        D.EXPIRY_DATE >= LIABILITY.EFFECTIVE_DATE
    )),*/
    CLASSIFICATION_ID     INTEGER ,
    CLASS_LIMIT1          INTEGER ,
    CLASS_LIMIT2          INTEGER ,
    USER_DEF1_OVERRIDE    INTEGER ,
    USER_DEF1_AUTOGEN     text,
    ANNUAL_PREMIUM2       numeric(15,2), /*COMPUTED BY (cast((select
sum(annual_premium) from premium_audit a
where a.policy_id = liability.policy_id and a.batch_no = liability.batch_no
and a.item_id = liability.origin_id) as NUMERIC(15,2))),*/
    OOS_BATCH_NO          INTEGER ,
    OOS_CHANGE            text DEFAULT 'N',
    OOS_INHERITANCE       text DEFAULT 'N',
    ANNUAL_PREM_OVERRIDE  text default 'N'
);

