CREATE TABLE OPTIONS (
    ITEM_NO               integer,
    OPTION_NO             integer,
    OPTION_CODE           text,
    DESCRIPTION           text,
    EFFECTIVE_DATE        timestamp,
    ACCOUNTING_DATE       timestamp,
    USER_ID               text,
    OPTION_KEY            text,
    LOCATION_NO           integer,
    STATE                 text,
    LIST                  SMALLINT default '0',
    DEDUCT                text,
    COVL                  text,
    DESCRIPT              text,
    DESCRIPT2             text,
    "LIMIT"                 integer,
    QTY                   integer,
    SEL                   text default 'Yes',
    ENDORSEMENT           text,
    MANUAL_RATE           numeric(15,2),
    DATE_FROM             timestamp,
    DATE_TO               timestamp,
    ACTIVITY              text default 'A',
    END_DATE              timestamp,
    UNIQUE_ID             integer,
    ORIGIN_ID             integer,
    BATCH_NO              integer,
    STATUS                text,
    DED_CODE              text default 'DED',
    COST                  NUMERIC(15,2) ,
    UNEARNEDCOST          NUMERIC(15,2) ,
    EXPIRY_DATE           timestamp,
    FORM_STATUS           text,
    POLICY_ID             INTEGER ,
    REFTABLE_ID           INTEGER ,
    DEDUCT_ID             INTEGER ,
    COVL_ID               INTEGER ,
    LKUPCODE              text,
    LKUPKEY               text,
    LKUPID                INTEGER ,
    OPTION_TYPE           text,
    ANNUAL_PREM           numeric(15,2), /*COMPUTED BY ((select cast(sum(annual_premium) as Numeric(15,2)) from premium_audit a 
where a.policy_id = options.policy_id and a.batch_no = options.batch_no 
and ( (a.origin_type = options.option_type) or ((a.origin_type = "D") and (options.option_type = "AO")) 
      or ((a.origin_type = "L") and (options.option_type = "AL")) ) and a.origin = options.origin_id)),*/
    ANNUAL_PREMIUM        numeric(15,2), /* COMPUTED BY (cast((select sum(annual_premium) from premium_audit a 
where a.policy_id = options.policy_id and a.batch_no = options.batch_no 
and ( (a.origin_type = options.option_type) or ((a.origin_type = "D") and (options.option_type = "AO")) 
    or ((a.origin_type = "L") and (options.option_type = "AL")) or ((a.origin_type = "V") and (options.option_type = "VO"))) 
     and a.origin = options.origin_id) as char(80))),*/
    PARENT_OPTION_NO      INTEGER ,
    PARENT_OPTION_TYPE    text,
    NUM_FIELD             NUMERIC(15,4),
    EXTERNALLY_ADDED      text,
    ANNUAL_PREMIUM2       numeric(15,2), /* COMPUTED BY (cast((select sum(annual_premium) from premium_audit a
where a.policy_id = options.policy_id and a.batch_no = options.batch_no
and ( (a.origin_type = options.option_type) or ((a.origin_type = "D") and (options.option_type = "AO"))
    or ((a.origin_type = "L") and (options.option_type = "AL")) or ((a.origin_type = "V") and (options.option_type = "VO")))
     and a.origin = options.origin_id) as NUMERIC(15, 2))),*/
    OOS_BATCH_NO          INTEGER ,
    OOS_CHANGE            text DEFAULT 'N',
    ORIGBATCH_NO          INTEGER ,
    MAX_LOSS              INTEGER DEFAULT 100,
    ANNUAL_PREM_OVERRIDE  text default 'N'
);

CREATE TABLE OTHER_COVERAGE (
    ITEM_NO               integer,
