    CLASS                 text default ' ',
    DESCR                 text default ' ',
    "LIMIT"                 integer,
    DEDUCT                text,
    RATE                  numeric(15,6),
    IRPM_FLAG             SMALLINT ,
    PREMIUM               numeric(15,2),
    EFFECTIVE_DATE        timestamp default 'now',
    ACCOUNTING_DATE       timestamp default 'now',
    USER_ID               text,
