    ORIGIN_ID             integer,
    STATUS                text,
    PREVBAL               numeric (15,2),
    EARNEDPREM            numeric (15,2),
    UNEARNEDPREM          numeric(15,6) ,
    WRITTENPREM           numeric(15,2), /*COMPUTED BY (PrevBal + Premium - unearnedPrem),*/
    BALANCE               numeric(15,2), /*COMPUTED BY (Premium - unearnedprem), */
    BASEPREM              NUMERIC(15,2) ,
    BASEEARNED            NUMERIC(15,2) ,
    BASEUNEARNED          NUMERIC(15,2) ,
    EXPIRY_DATE           timestamp,
    DED_TABLE             text,
    POLICY_ID             INTEGER ,
    DEDUCT_ID             INTEGER ,
    ANNUAL_PREMIUM        numeric(15,2), /* COMPUTED BY (cast((select 
sum(annual_premium) from premium_audit a 
where a.policy_id = other_coverage.policy_id and a.batch_no = other_coverage.batch_no and a.item_id = other_coverage.origin_id) as char(80))),*/
    ORIGBATCH_NO          INTEGER ,
    RATE_TYPE             text,
    OOS_BATCH_NO          INTEGER ,
    OOS_CHANGE            text DEFAULT 'N',
    OOS_INHERITANCE       text DEFAULT 'N',
    MAX_LOSS              INTEGER DEFAULT 100,
